using System.Collections.Generic;
using UnityEngine;
using Kingsfall.Chess;

namespace Kingsfall
{
    /// <summary>
    /// Last words and death cries for captured pieces. Clips are generated by Tools/make_voices.py
    /// into Resources/Voices; lines.txt maps each clip to its subtitle for the speech bubble.
    /// </summary>
    public class PieceVoices : MonoBehaviour
    {
        public static PieceVoices I { get; private set; }
        public bool Enabled = true;
        public float Volume = 1f;

        // speech bubble for the UI
        public string BubbleText { get; private set; } = "";
        public Vector3 BubblePosition { get; private set; }
        public float BubbleAlpha { get; private set; }

        static readonly string[] Keys = { "", "pawn", "knight", "bishop", "rook", "queen", "king" };
        readonly Dictionary<string, List<AudioClip>> bank = new Dictionary<string, List<AudioClip>>();
        readonly Dictionary<string, List<AudioClip>> bags = new Dictionary<string, List<AudioClip>>();
        readonly Dictionary<string, string> subtitle = new Dictionary<string, string>();
        AudioSource lineSrc, crySrc;
        PieceView speaker;
        float bubbleUntil;

        void Awake()
        {
            I = this;
            lineSrc = gameObject.AddComponent<AudioSource>();
            crySrc = gameObject.AddComponent<AudioSource>();
            foreach (var s in new[] { lineSrc, crySrc }) { s.playOnAwake = false; s.spatialBlend = 0f; }

            var index = Resources.Load<TextAsset>("Voices/lines");
            if (index)
                foreach (var row in index.text.Split('\n'))
                {
                    int bar = row.IndexOf('|');
                    if (bar > 0) subtitle[row.Substring(0, bar)] = row.Substring(bar + 1).Trim();
                }
            foreach (var clip in Resources.LoadAll<AudioClip>("Voices"))
            {
                var parts = clip.name.Split('_'); // pawn_line_03
                if (parts.Length < 3) continue;
                string key = parts[0] + "_" + parts[1];
                if (!bank.TryGetValue(key, out var list)) bank[key] = list = new List<AudioClip>();
                list.Add(clip);
            }
        }

        AudioClip Pick(string key)
        {
            if (!bank.TryGetValue(key, out var all) || all.Count == 0) return null;
            // shuffle bag: every line is heard before any repeats
            if (!bags.TryGetValue(key, out var bag) || bag.Count == 0)
            {
                bags[key] = bag = new List<AudioClip>(all);
                for (int i = bag.Count - 1; i > 0; i--) { int j = Random.Range(0, i + 1); (bag[i], bag[j]) = (bag[j], bag[i]); }
            }
            var c = bag[bag.Count - 1];
            bag.RemoveAt(bag.Count - 1);
            return c;
        }

        /// <summary>The victim pleads as the attacker closes in.</summary>
        public void LastWords(PieceView victim)
        {
            if (!Enabled || !victim) return;
            var clip = Pick(Keys[(int)victim.Type] + "_line");
            if (!clip) return;
            lineSrc.Stop();
            lineSrc.clip = clip;
            lineSrc.volume = Volume;
            lineSrc.pitch = 1f;
            lineSrc.Play();
            speaker = victim;
            BubbleText = subtitle.TryGetValue(clip.name, out var t) ? t : "";
            bubbleUntil = Time.unscaledTime + clip.length + 0.6f;
        }

        /// <summary>The moment of destruction.</summary>
        public void Cry(PieceView victim)
        {
            if (!Enabled || !victim) return;
            // let a joke that is nearly finished land instead of talking over it
            if (lineSrc.isPlaying && lineSrc.clip && lineSrc.clip.length - lineSrc.time > 0.5f) return;
            var clip = Pick(Keys[(int)victim.Type] + "_cry");
            if (!clip) return;
            crySrc.clip = clip;
            crySrc.volume = Volume;
            crySrc.pitch = Random.Range(0.97f, 1.04f);
            crySrc.Play();
            speaker = victim;
            BubbleText = subtitle.TryGetValue(clip.name, out var t) ? t : "";
            bubbleUntil = Time.unscaledTime + clip.length + 0.5f;
        }

        public void Silence()
        {
            lineSrc.Stop();
            crySrc.Stop();
            bubbleUntil = 0f;
        }

        void LateUpdate()
        {
            if (speaker && speaker.gameObject.activeInHierarchy)
                BubblePosition = speaker.Body.position + Vector3.up * (speaker.Height + 0.25f);
            float target = Time.unscaledTime < bubbleUntil && Enabled ? 1f : 0f;
            BubbleAlpha = Mathf.MoveTowards(BubbleAlpha, target, Time.unscaledDeltaTime * 5f);
        }
    }
}
